/* Bootstrap JS loader (CDN)
	 This small wrapper dynamically inserts the official Bootstrap bundle from CDN.
	 Using this approach avoids committing minified vendor code while keeping local path compatibility.
*/
(function(){
	if(typeof window.bootstrap !== 'undefined') return;
	var s = document.createElement('script');
	s.src = 'https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/js/bootstrap.bundle.min.js';
	s.crossOrigin = 'anonymous';
	s.defer = false;
	document.head.appendChild(s);
})();
